const SYSTEM_METHODS: &[BuiltinMethod] = &[
    bm("currentTimeMillis", &[], BRet::Long, "()J"),
    bm("nanoTime", &[], BRet::Long, "()J"),
    // `arraycopy(Object src, int srcPos, Object dest, int destPos, int len)`,
    // typed as javac types it: any reference. caturra used to demand arrays
    // statically, which refused the legal `Object`-typed call; the VM now
    // throws the JDK's "source type X is not an array" ArrayStoreException,
    // so the runtime check does the job the strictness was standing in for.
    bm(
        "arraycopy",
        &[BParam::Object, I, BParam::Object, I, I],
        BRet::Void,
        "(Ljava/lang/Object;ILjava/lang/Object;II)V",
    ),
    bm("lineSeparator", &[], BRet::Str, "()Ljava/lang/String;"),
    // Identity hash: stable per object for a run (the heap reference), 0 for
    // null. The VALUE differs from any real JVM's (which hands out address
    // bits) — only the identity properties are portable, and they hold.
    bm(
        "identityHashCode",
        &[BParam::Object],
        BRet::Int,
        "(Ljava/lang/Object;)I",
    ),
    // Internal: box a value whose static type is `Object` but whose runtime
    // representation may be an unboxed primitive — the read of a collection
    // element the type system only knows as a wildcard or a type variable.
    // Never reachable from source (`__` names cannot be written).
    bm(
        "__box",
        &[BParam::Object],
        BRet::Object,
        "(Ljava/lang/Object;)Ljava/lang/Object;",
    ),
    // Terminate the program with the given status code (Java's System.exit).
    bm("exit", &[I], BRet::Void, "(I)V"),
    // Internal standard-out capture, used only by the bundled
    // SystemOutTestRunner (org.code.validation): one String per print/println.
    bm("__captureStart", &[], BRet::Void, "()V"),
    bm("__captureEnd", &[], BRet::StrArray, "()[Ljava/lang/String;"),
    // Internal Swing event pump, used only by the bundled __SwingRuntime:
    // render the current component tree (JSON), block until the next UI
    // event, and return its payload (or null when the window is closed).
    bm(
        "__uiAwait",
        &[S],
        BRet::Str,
        "(Ljava/lang/String;)Ljava/lang/String;",
    ),
    // Internal blocking dialog (bundled JOptionPane): show a modal of the
    // given kind with the message, block until the user answers, and return
    // the response (a code / entered text, or null if dismissed).
    bm(
        "__uiDialog",
        &[S, S],
        BRet::Str,
        "(Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;",
    ),
    // Internal image-pixel bridge, used only by the bundled org.code.media.Image:
    // the host preloads a named asset's pixels into the VFS as bytes (u32 width,
    // u32 height, then RGB triples) and these hand the whole buffer across in one
    // native call — a 400x400 image is 160k pixels, far too many to ferry through
    // the interpreter a token at a time. `__writeImage` sends an edited image back
    // out for the host to draw.
    bm(
        "__imageDims",
        &[S],
        BRet::IntArray,
        "(Ljava/lang/String;)[I",
    ),
    bm(
        "__imagePixels",
        &[S],
        BRet::IntArray,
        "(Ljava/lang/String;)[I",
    ),
    bm(
        "__writeImage",
        &[S, I, I, BParam::RefArray],
        BRet::Void,
        "(Ljava/lang/String;II[I)V",
    ),
    // Sound samples, for the same reason and then some: `beat.wav` is 4.9 MILLION
    // samples, crossing as signed 16-bit PCM bytes. They used to be TEXT, which
    // `SoundLoader.read` parsed one interpreted `Scanner.nextInt()` at a time and
    // `playSound` built one interpreted `StringBuilder.append` at a time — and
    // nobody noticed, because a missing asset used to hand back silence and so no
    // level ever read a real sound.
    bm(
        "__soundSamples",
        &[S],
        BRet::DoubleArray,
        "(Ljava/lang/String;)[D",
    ),
    bm(
        "__writeSound",
        &[S, BParam::RefArray],
        BRet::Void,
        "(Ljava/lang/String;[D)V",
    ),
];

